import json, glob, os, datetime

tasks = {
    'task-9e4a81f22c4043019d59': '系统功能与架构图绘制',
    'task-56b365522a3e48799f60': '领导欢送祝福视频',
    'task-2811b8ca0d2341ea93c9': '本地部署项目',
}
# 找每个task与当前项目相关的jsonl（取最新的完整版本）
for tid, title in tasks.items():
    files = glob.glob(f'*/{tid}.session.execution.jsonl')
    files.sort(key=lambda f: os.path.getsize(f), reverse=True)
    if not files: 
        print(tid, 'NO FILE'); continue
    fp = files[0]
    print(f'\n===== {tid} | {title} | {fp} | {os.path.getsize(fp)/1024/1024:.1f}MB =====')
    users = []
    last_assistant_texts = []
    n = 0
    with open(fp) as f:
        for line in f:
            n += 1
            try: d = json.loads(line)
            except: continue
            role = d.get('role')
            if role == 'user':
                for p in d.get('parts', []):
                    if p.get('type') == 'text':
                        t = p.get('data', {}).get('text', '')
                        if t and not t.startswith('<'):
                            users.append(t[:150].replace('\n', ' '))
            elif role == 'assistant':
                txt = ''
                for p in d.get('parts', []):
                    if p.get('type') == 'text':
                        txt += p.get('data', {}).get('text', '')
                if txt.strip():
                    last_assistant_texts.append(txt[:300].replace('\n', ' '))
    print(f'总行数: {n}, user消息: {len(users)}')
    print('--- 用户消息列表(前30条):')
    for u in users[:30]:
        print('  *', u)
    print('--- 最后一条assistant输出:')
    if last_assistant_texts:
        print('  ', last_assistant_texts[-1][:300])
EOF
